import sys

def solve():
    input = sys.stdin.read
    data = input().strip().split()

    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    for k in range(n):
        valid = True
        for i in range(n):
            # If i is even (0-indexed), gear rotates clockwise: value increases by k % n
            # If i is odd, gear rotates counter-clockwise: value decreases by k % n
            shift = k % n
            if i % 2 == 0:
                val = (a[i] + shift) % n
            else:
                val = (a[i] - shift) % n

            if val != i:
                valid = False
                break

        if valid:
            print("Yes")
            return

    print("No")

if __name__ == "__main__":
    solve()
